import random

GROUP = "number_theory"
SKILL = "induction"


def find_max_exponent(n, min_exp, max_exp):
    if n == 0:
        return 0

    if n < min_exp:
        return -1

    max_count = 0

    for exponent in range(min_exp, max_exp + 1):
        if exponent <= n:
            remaining_n = n - exponent
            count = find_max_exponent(remaining_n, min_exp, exponent - 1)

            if count != -1:
                max_count = max(max_count, count + 1)

    return max_count


def generate(seed):
    rng = random.Random(seed)

    min_exp = rng.randint(2, 5)
    max_exp = rng.randint(5, 15)
    n = rng.randint(1000, 5000)

    answer = find_max_exponent(n, min_exp, max_exp)

    check = -1
    for exponent in range(min_exp, max_exp + 1):
        if exponent <= n:
            remaining_n = n - exponent
            count = find_max_exponent(remaining_n, min_exp, exponent - 1)
            if count != -1:
                check = max(check, 1 + count)

    assert answer == check, f"answer={answer} check={check}"

    problem = (
        f"Consider the integers from {min_exp} to {max_exp} (inclusive). "
        f"What is the maximum number of distinct integers that can be selected such that no integer exceeds the total {n} and all selected integers sum to exactly {n}? State only the integer."
    )
    return problem, str(answer)

