def find_max_non_intersecting_points(grid_size, min_x, max_x):
    if grid_size == 0:
        return 0

    if grid_size < min_x:
        return -1

    max_count = 0

    for x in range(min_x, max_x + 1):
        if x <= grid_size:
            remaining_size = grid_size - x
            count = find_max_non_intersecting_points(remaining_size, min_x, x - 1)

            if count != -1:
                max_count = max(max_count, count + 1)

    return max_count


def generate(seed):
    rng = random.Random(seed)

    min_x = rng.randint(2, 5)
    max_x = rng.randint(5, 15)
    grid_size = rng.randint(1000, 5000)

    answer = find_max_non_intersecting_points(grid_size, min_x, max_x)

    check = -1
    for x in range(min_x, max_x + 1):
        if x <= grid_size:
            remaining_size = grid_size - x
            count = find_max_non_intersecting_points(remaining_size, min_x, x - 1)
            if count != -1:
                check = max(check, 1 + count)

    assert answer == check, f"answer={answer} check={check}"

    problem = (
        f"Consider the grid points with integer coordinates from ({min_x}, 0) to ({max_x}, 0) (inclusive) on the x-axis. What is the maximum number of distinct points that can be selected such that no point exceeds the total grid size of {grid_size} and all selected points sum to exactly {grid_size}? State only the integer."
    )
    return problem, str(answer)

